#include "fuse/capability.h"
namespace fuse {
Status registry_initialize(CapabilityRegistry*r){if(!r)return Status::InvalidArgument;r->entries={CapabilityDescriptor{CAP_SYSTEM_STATUS,"SYSTEM_STATUS",CapabilityEffect::NONE,ReplayClass::RECOMPUTE_SAFE},{CAP_SHA256,"SHA256",CapabilityEffect::NONE,ReplayClass::RECOMPUTE_SAFE},{CAP_FILE_HASH,"FILE_HASH",CapabilityEffect::READ_ONLY,ReplayClass::RECOMPUTE_SAFE},{CAP_FILE_WRITE_ATOMIC,"FILE_WRITE_ATOMIC",CapabilityEffect::REVERSIBLE,ReplayClass::RECEIVER_RECONCILE}};FcbWriter w{};fcb_begin(&w,0x3001,0);for(u32 i=0;i<4;i++){u8 b[8]{};put_u32_le(b,r->entries[i].id);put_u16_le(b+4,(u16)r->entries[i].effect);put_u16_le(b+6,(u16)r->entries[i].replay);fcb_put_bytes(&w,i+1,FcbType::BYTES,{b,8});}Buffer out;return fcb_finish(&w,&out,&r->root_hash);}Status registry_find(const CapabilityRegistry*r,u32 id,const CapabilityDescriptor**out){if(!r||!out)return Status::InvalidArgument;for(auto&x:r->entries)if(x.id==id){*out=&x;return Status::Ok;}return Status::Unsupported;}
}
